#pragma material(ShadingModel = Unlit, Backend = Graph)

#pragma region Parameters
uniform float A = 1.0;
uniform float B = 2.0;
#pragma endregion

export void M_RtRegions(inout material m)
{
    #pragma region Maths
    float Sum = A + B;
    float Scaled = Sum * 0.5;
    #pragma endregion

    m.EmissiveColor = float3(Scaled, Scaled, Scaled);
    m.Opacity = Scaled;
}

#pragma layout(Node, Var = B, X = 0, Y = -444)
#pragma layout(Node, Var = A, X = 0, Y = -620)
#pragma layout(Node, Var = Sum, X = 290, Y = -536)
#pragma layout(Node, Var = Scaled, X = 580, Y = -451)
